func:
// Disaridan gelen her cagri bazen basarisiz olur: servis kapalidir,
// dosya kilitlidir, kota dolmustur. Bu dugum onu taklit eder.
//
// Deneme sayaci msg uzerinde tasinir, context'te DEGIL.
// Sebep: her tetikleme kendi sayacini tasimali. flow.set() kullansak
// bir onceki tetiklemenin sayaci yenisine sizardi.

msg.deneme = (msg.deneme || 0) + 1;

// Ilk iki deneme kasitli olarak patlar, ucuncusu gecer.
// Gercek hayatta bu kosul yerine bir API cagrisi olur.
const gecmesiGerekenDeneme = 3;

if (msg.deneme < gecmesiGerekenDeneme) {
  // node.status(): dugumun altindaki kucuk rozet. Sadece gorseldir,
  // akisa mesaj GONDERMEZ. status dugumu bunu yakalar.
  node.status({ fill: "red", shape: "ring", text: `deneme ${msg.deneme} basarisiz` });

  // KRITIK FARK:
  //   throw new Error(...)  -> akis durur, catch dugumu yakalar
  //   node.error(metin)     -> sadece log'a yazar, catch YAKALAMAZ
  //   node.error(metin, msg) -> catch YAKALAR (msg parametresi sart)
  //
  // Ikinci parametreyi unutmak en sik yapilan hatadir.
  node.error(`Servis yanit vermedi (deneme ${msg.deneme})`, msg);
  return null; // mesaji burada durdur; catch dali devrali
}

node.status({ fill: "green", shape: "dot", text: `deneme ${msg.deneme} OK` });

msg.payload = {
  sonuc: "islem tamamlandi",
  kacinciDenemede: msg.deneme
};

return msg;

// catch dugumu, yakaladigi hatayi msg.error icine koyar.
// Sozlesme (Node-RED standardi):
//   msg.error.message      -> hata metni
//   msg.error.source.id    -> hatayi ureten dugumun ID'si
//   msg.error.source.type  -> dugum tipi (function, http request, file...)
//   msg.error.source.name  -> dugumun adi
//
// Orijinal msg'nin diger alanlari KORUNUR. msg.deneme bu yuzden
// hala elimizde -- yeniden deneme sayacini oradan okuyabiliyoruz.

const hata = msg.error || {};
const kaynak = hata.source || {};

const ENUST_DENEME = 3;
const deneme = msg.deneme || 0;

// Her hata yeniden denenmeye degmez. Kalici hatalari (yetki, gecersiz
// veri) tekrar denemek sadece zaman kaybidir; sadece gecici olanlari
// yeniden deneyin.
const metin = String(hata.message || "");
const geciciMi = /timeout|ECONNREFUSED|yanit vermedi|503|502|429/i.test(metin);

msg.hataOzeti = {
  mesaj: metin,
  dugum: kaynak.name || kaynak.type || "bilinmiyor",
  dugumTipi: kaynak.type || "-",
  deneme: deneme,
  gecici: geciciMi
};

if (geciciMi && deneme < ENUST_DENEME) {
  msg.karar = "yeniden-dene";
  node.status({ fill: "yellow", shape: "ring", text: `yeniden deneniyor (${deneme}/${ENUST_DENEME})` });
} else {
  msg.karar = "vazgec";
  node.status({ fill: "red", shape: "dot", text: geciciMi ? "deneme hakki bitti" : "kalici hata" });
}

return msg;

// Production mode'da editor kapalidir: debug panelini goremezsiniz.
// Hatanin tek kalici izi bu dosyadir. Ders 4'teki file dugumunun
// gercek bir ise yaradigi yer burasi.

const o = msg.hataOzeti || {};
const zaman = new Date().toLocaleString("tr-TR");

// Tek satir, ayrilmis alanlar: sonradan grep/Excel ile okunabilsin.
msg.payload = [
  zaman,
  o.gecici ? "GECICI" : "KALICI",
  `deneme=${o.deneme}`,
  `dugum=${o.dugum}`,
  `mesaj=${o.mesaj}`
].join(" | ");

msg.topic = "hata-gunlugu";

return msg;
